WITH перечни AS (SELECT DISTINCT x[1] AS имя FROM project_documents m CROSS JOIN LATERAL regexp_matches(m.content, '(TC-[A-Z]+-[0-9]+[a-z]?|US-[A-Z]+-[0-9]+|SCR-[A-Z]+-[0-9]+)', 'g') AS x WHERE m.project_id = $1 AND m.entity_kind = 'milestone') SELECT 'этапов не заведено: покрытие ими не сверялось' AS detail WHERE NOT EXISTS (SELECT 1 FROM project_documents WHERE project_id = $1 AND entity_kind = 'milestone') UNION ALL SELECT c.id || ' — проверка вне всех этапов' FROM project_checks c WHERE c.project_id = $1 AND EXISTS (SELECT 1 FROM перечни) AND NOT EXISTS (SELECT 1 FROM перечни p WHERE p.имя = c.id) AND true UNION ALL SELECT s.id || ' — история вне всех этапов' FROM project_stories s WHERE s.project_id = $1 AND EXISTS (SELECT 1 FROM перечни) AND NOT EXISTS (SELECT 1 FROM перечни p WHERE p.имя = s.id) AND true UNION ALL SELECT sc.id || ' — экран вне всех этапов' FROM project_screens sc WHERE sc.project_id = $1 AND sc.out_of_version = '' AND EXISTS (SELECT 1 FROM перечни) AND NOT EXISTS (SELECT 1 FROM перечни p WHERE p.имя = sc.id) AND true ORDER BY 1
